cd /tmp; jq -c '.components.schemas.FeatureValueTypeEnum' swag.json; E=[env-51f8dbd4c8114156]; cat > exp.json <<'EOF'
{
  "feature": 225,
  "name": "live_chat_copy test",
  "hypothesis": "\"Get it today\" increases checkout completed versus \"Buy now\"",
  "metrics": [
    {"metric": "checkout_completed", "expected_direction": "increase"},
    {"metric": "refund_requested", "expected_direction": "not_increase"}
  ],
  "experiment_rollout": {
    "enabled": false,
    "rollout_percentage": 100,
    "feature_state_value": {"type": "unicode", "value": "Buy now"},
    "multivariate_feature_state_values": [
      {"multivariate_feature_option": 24, "percentage_allocation": 50}
    ]
  }
}
EOF
flagsmith api "api/v1/environments/$E/experiments/" -X POST --input exp.json --json 2>&1 | jq .

